    const autoScript=autoPrint?'<script>window.addEventListener("load",()=>setTimeout(()=>window.print(),250));<\/script>':'';
    const html=`<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>견적서 ${esc(d.document_no||'')}</title><style>${css}</style></head><body><div class="df55-toolbar"><button type="button" onclick="window.print()">인쇄 / PDF</button></div><main class="df55-page"><h1 class="df55-title">견 적 서</h1><div class="df55-title-rule"></div><section class="df55-head"><div class="df55-left"><div class="df55-row"><div class="label">수 신</div><div class="value">${esc(recipient||'-')}</div></div><div class="df55-row"><div class="label">담당자</div><div class="value">${esc(contact||'-')}</div></div><div class="df55-left-sep"></div><div class="df55-row"><div class="label">견적번호</div><div class="value">${esc(d.document_no||'-')}</div></div><div class="df55-row"><div class="label">작성일자</div><div class="value">${esc(d.issue_date||'-')}</div></div><div class="df55-left-sep"></div><div class="df55-statement">위와 같이 견적합니다.</div><div class="df55-totalbox"><div class="tlabel">총 금액</div><div><div class="tvalue">₩${number(total)}</div><div class="vat">(VAT 포함)</div></div></div><div class="df55-email"><div class="label">담당자 메일</div><div class="value">${esc(email)}</div></div></div><div class="df55-right"><div class="df55-company-row"><div class="label">상 호</div><div class="value">${esc(s.supplier_name||'-')}</div></div><div class="df55-company-row"><div class="label">사업자번호</div><div class="value">${esc(s.supplier_biz_no||'-')}</div></div><div class="df55-company-row"><div class="label">대표자</div><div class="value df55-rep-value"><span>${esc(s.supplier_representative||'-')}</span><img class="df55-seal" src="${seal}" data-fallback="${sealFallback}" onerror="this.onerror=null;this.src=this.dataset.fallback" alt="인감"></div></div><div class="df55-company-row"><div class="label">전화</div><div class="value">${esc(s.supplier_phone||'-')}</div></div><div class="df55-company-row"><div class="label">팩스</div><div class="value">${esc(s.supplier_fax||'-')}</div></div><div class="df55-company-row"><div class="label">주소</div><div class="value">${esc(s.supplier_address||'-')}</div></div></div></section><section class="df55-table-wrap"><table class="df55-table"><colgroup><col class="c-no"><col class="c-item"><col class="c-spec"><col class="c-qty"><col class="c-unit"><col class="c-supply"><col class="c-tax"></colgroup><thead><tr><th>번호</th><th>품목</th><th>규격</th><th>수량</th><th>단가</th><th>공급가액</th><th>세액</th></tr></thead><tbody>${rowHtml}</tbody></table></section><div class="df55-summary"><div class="df55-sum-row"><div class="label">공급가액</div><div class="value">${number(sub)}</div></div><div class="df55-sum-row"><div class="label">VAT (10%)</div><div class="value">${number(tax)}</div></div>${discountRow}<div class="df55-sum-row total"><div class="label">합계금액</div><div class="value">${number(total)}</div></div></div><section class="df55-notes"><div class="df55-notes-title">비고</div><ol>${noteItems}</ol></section><div class="df55-footer"><span>DREAMFOREN&nbsp;&nbsp;|&nbsp;&nbsp;Dream For Environment</span><span>${esc(d.document_no||'견적서')}</span></div></main>${autoScript}</body></html>`;
